-- Selected calls from app:pim_schema_api_test in spiralscout/pim/test.
local test = require("test")
local schema = require("schema")
local attr_code = "material"
local up, uerr = schema.update_option(attr_code, "red", { labels = { en_US = "Crimson" }, sort_order = 20 }, "user:schema-admin")
test.is_nil(uerr)
test.eq(up.labels.en_US, "Crimson")
local down, dderr = schema.disable_option(attr_code, "red", "user:schema-admin")
test.is_nil(dderr)
test.eq(down.enabled, false)
local created, cerr = schema.create_family({ code = "accessories", labels = { en_US = "Accessories" }, attributes = { "sku", "title" } }, "user:schema-editor")
test.is_nil(cerr)
test.eq(created.system, false)
local chu, chuerr = schema.update_channel("print", { labels = { en_US = "Print Channel" } }, "user:schema-admin")
test.is_nil(chuerr)
test.eq(chu.labels.en_US, "Print Channel")
local chd, chderr = schema.disable_channel("print", "user:schema-admin")
test.is_nil(chderr)
test.eq(chd.enabled, false)
local gu, guerr = schema.update_group("technical", { sort_order = 75 }, "user:schema-admin")
test.is_nil(guerr)
test.eq(gu.sort_order, 75)
